mapper.select:
WITH ranked AS ( SELECT PD.productdetailid, PD.productid, TO_CHAR(PD.price, 'FM999,999,999') AS price, PD.productimage, PD.subimage, P.productname, PD.size, PD.color, COALESCE( STRING_AGG(DISTINCT PD2.color, ',' ORDER BY PD2.color), '' ) AS availableColors, ROW_NUMBER() OVER (PARTITION BY PD.productid, PD.color ORDER BY PD.productdetailid) AS rn
FROM productdetails PD JOIN product P ON PD.productid = P.productid JOIN productdetails PD2 ON PD.productid = PD2.productid
PD.isdeleted = FALSE AND P.isdeleted = FALSE
AND PD.color IN
#{color}
AND PD.size IN
#{size}
AND PD.price >= #{minPrice}
AND PD.price <= #{maxPrice}
AND P.subcategoryid = #{subCategoryId}
GROUP BY PD.productdetailid, PD.productid, PD.price, PD.productimage, PD.subimage, P.productname, PD.size, PD.color )
SELECT * FROM ranked WHERE rn = 1
ORDER BY
price quantity productdetailid
DESC ASC
LIMIT #{limit} OFFSET #{offset}
